<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { http, errorMessage } from '../../api/http'
import type { Page, User } from '../../types'
import { dateTime } from '../../utils/format'
import { useAuth } from '../../stores/auth'
import LoadingState from '../../components/LoadingState.vue'
import Pagination from '../../components/Pagination.vue'
import ConfirmDialog from '../../components/ConfirmDialog.vue'
const auth = useAuth(), result = ref<Page<User>>(), loading = ref(true), busy = ref(false), error = ref(''), success = ref('')
const filters = reactive({ search: '', role: '', isActive: '' })
const target = ref<{ user: User; kind: 'status' | 'role' }>()
async function load(page = 1) { loading.value = true; error.value = ''; try { result.value = (await http.get<Page<User>>('/admin/users', { params: { ...filters, isActive: filters.isActive || undefined, role: filters.role || undefined, page } })).data } catch(e) { error.value = errorMessage(e) } finally { loading.value = false } }
async function change() { if (!target.value || busy.value) return; const { user, kind } = target.value; target.value = undefined; busy.value = true; error.value = ''; success.value = ''; try { await http.patch(`/admin/users/${user.id}/${kind}`, kind === 'status' ? { isActive: !user.isActive } : { role: user.role === 'Admin' ? 'Customer' : 'Admin' }); success.value = 'Đã cập nhật tài khoản.'; await load(result.value?.page) } catch(e) { error.value = errorMessage(e) } finally { busy.value = false } }
onMounted(() => load())
</script>
<template><div class="section-heading"><div><span class="eyebrow">CỘNG ĐỒNG BOOKNEST</span><h1>Quản lý người dùng</h1><p>Tra cứu tài khoản, quản lý quyền và trạng thái truy cập.</p></div></div><p v-if="error" class="alert error" role="alert">{{ error }} <button @click="load()">Thử lại</button></p><p v-if="success" class="alert success" role="status">{{ success }}</p><section class="panel"><form class="toolbar" @submit.prevent="load()"><input v-model="filters.search" aria-label="Tìm người dùng" placeholder="Họ tên hoặc email…"><select v-model="filters.role" aria-label="Vai trò"><option value="">Tất cả vai trò</option><option value="Admin">Admin</option><option value="Customer">Customer</option></select><select v-model="filters.isActive" aria-label="Trạng thái"><option value="">Tất cả trạng thái</option><option value="true">Hoạt động</option><option value="false">Bị khóa</option></select><button class="btn secondary">Tìm kiếm</button></form><p class="user-total" role="status">{{ result?.totalItems || 0 }} người dùng phù hợp</p><LoadingState v-if="loading" /><div v-else class="table-wrap"><table class="users-table"><thead><tr><th>Người dùng</th><th>Email</th><th>Điện thoại</th><th>Vai trò</th><th>Trạng thái</th><th>Ngày tạo</th><th>Thao tác</th></tr></thead><tbody><tr v-for="u in result?.items" :key="u.id"><td><div class="user-cell"><span class="user-initial">{{ u.fullName.charAt(0).toUpperCase() }}</span><strong>{{ u.fullName }}</strong></div></td><td>{{ u.email }}</td><td>{{ u.phoneNumber || '—' }}</td><td><span class="badge" :class="u.role === 'Admin' ? 'paid' : ''">{{ u.role }}</span></td><td><span class="badge" :class="u.isActive ? 'paid' : 'cancelled'">{{ u.isActive ? 'Hoạt động' : 'Bị khóa' }}</span></td><td>{{ dateTime(u.createdAt) }}</td><td><div class="user-actions"><RouterLink class="text-link" :to="`/admin/users/${u.id}`">Chi tiết</RouterLink><button class="btn secondary small" :disabled="busy || u.id === auth.user?.id" @click="target = { user: u, kind: 'status' }">{{ u.isActive ? 'Khóa' : 'Mở khóa' }}</button><button class="btn secondary small" :disabled="busy || u.id === auth.user?.id" @click="target = { user: u, kind: 'role' }">{{ u.role === 'Admin' ? 'Hạ quyền' : 'Cấp quyền Admin' }}</button></div></td></tr><tr v-if="!result?.items.length"><td colspan="7">Không có người dùng phù hợp.</td></tr></tbody></table></div><Pagination v-if="result" :page="result.page" :total-pages="result.totalPages" @change="load" /></section><ConfirmDialog :open="!!target" :title="target?.kind === 'status' ? 'Thay đổi trạng thái tài khoản?' : 'Thay đổi vai trò?'" :message="target ? `${target.user.fullName} (${target.user.email}): ${target.kind === 'status' ? (target.user.isActive ? 'Khóa tài khoản và thu hồi mọi phiên đăng nhập.' : 'Mở khóa tài khoản. Người dùng cần đăng nhập lại.') : `Đổi vai trò thành ${target.user.role === 'Admin' ? 'Customer' : 'Admin'} và thu hồi mọi phiên đăng nhập.`} Đơn hàng và đánh giá được giữ nguyên.` : ''" @close="target = undefined" @confirm="change" /></template>
<style scoped>.user-total { margin:0 0 16px; font-size:14px; }.users-table { min-width:1100px; }.user-cell { display:flex; align-items:center; gap:10px; }.user-initial { display:flex; align-items:center; justify-content:center; width:34px; height:34px; border-radius:50%; background:#eef3ff; color:#2457d6; flex-shrink:0; }.user-actions { display:flex; align-items:center; gap:8px; }.user-actions .btn { white-space:nowrap; }.user-cell strong { min-width:130px; }</style>